import React, { useState, useEffect, useCallback } from 'react';
import styled, { css } from 'styled-components';
import { motion, AnimatePresence } from 'framer-motion';
import { FaBars, FaTimes, FaChevronDown, FaSignOutAlt } from 'react-icons/fa';

/**
 * CashPilot Mobile-First Responsive Menu
 * =====================================
 * Sistema de navegação com:
 * - Mobile: Header fixo + Menu hamburguer drawer
 * - Desktop: Sidebar fixa com animações
 */

// ============= STYLES =============

// Container principal
const MobileMenuContainer = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: var(--z-mobile-menu);
`;

// Header Fixo Mobile
const MobileHeader = styled.header`
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: calc(var(--z-mobile-menu) + 100);
  
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  padding-top: calc(var(--space-sm) + env(safe-area-inset-top, 0));
  
  background: rgba(15, 23, 42, 0.95);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  
  border-bottom: 1px solid rgba(56, 189, 248, 0.1);
  height: 60px;
  min-height: 60px;
  
  /* Desktop: hide mobile header */
  @media (min-width: 1024px) {
    display: none;
  }
`;

const MobileLogo = styled.h1`
  font-size: var(--fs-lg);
  font-weight: var(--fw-bold);
  color: #38bdf8;
  margin: 0;
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  
  /* Desktop: hide */
  @media (min-width: 1024px) {
    display: none;
  }
`;

const MenuToggle = styled.button`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  
  background: rgba(56, 189, 248, 0.1);
  border: 1px solid rgba(56, 189, 248, 0.2);
  border-radius: var(--radius-md);
  
  color: #38bdf8;
  font-size: var(--fs-lg);
  cursor: pointer;
  
  transition: all var(--transition-fast);
  -webkit-tap-highlight-color: transparent;
  
  &:hover {
    background: rgba(56, 189, 248, 0.2);
  }
  
  &:active {
    transform: scale(0.95);
  }
`;

// Overlay backdrop
const Overlay = styled(motion.div)`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.6);
  z-index: calc(var(--z-mobile-menu) + 50);
  
  /* Safe area for iPhone notch */
  @supports (padding: env(safe-area-inset-top)) {
    padding-top: env(safe-area-inset-top);
  }
`;

// Panel do menu mobile
const MenuPanel = styled(motion.div)`
  position: fixed;
  top: 0;
  right: 0;
  width: 280px;
  max-width: 85vw;
  height: 100%;
  
  background: #1e293b;
  z-index: calc(var(--z-mobile-menu) + 100);
  box-shadow: -10px 0 40px rgba(0, 0, 0, 0.5);
  
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  
  /* Safe area for iPhone notch */
  @supports (padding: env(safe-area-inset-top)) {
    padding-top: calc(env(safe-area-inset-top) + 60px);
  }
`;

const MenuHeader = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md);
  border-bottom: 1px solid rgba(148, 163, 184, 0.1);
`;

const MenuLogo = styled.div`
  font-size: var(--fs-xl);
  font-weight: var(--fw-bold);
  color: #38bdf8;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
`;

const CloseButton = styled.button`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  
  background: transparent;
  border: none;
  border-radius: var(--radius-md);
  
  color: #94a3b8;
  font-size: var(--fs-xl);
  cursor: pointer;
  
  transition: all var(--transition-fast);
  
  &:hover {
    background: rgba(148, 163, 184, 0.1);
    color: #f8fafc;
  }
  
  &:active {
    transform: scale(0.95);
  }
`;

const MenuContent = styled.div`
  padding: var(--space-md);
  padding-bottom: calc(var(--space-md) + env(safe-area-inset-bottom, 0));
`;

const Section = styled.div`
  margin-bottom: var(--space-lg);
  
  @media (min-width: 1024px) {
    margin-bottom: var(--space-md);
  }
`;

const SectionHeader = styled.button`
  display: flex;
  align-items: center;
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  
  background: ${props => props.$expanded
    ? 'rgba(102, 126, 234, 0.1)'
    : 'transparent'};
  border: none;
  border-radius: var(--radius-md);
  
  color: ${props => props.$expanded ? '#667eea' : '#94a3b8'};
  font-size: var(--fs-sm);
  font-weight: var(--fw-semibold);
  
  cursor: pointer;
  transition: all var(--transition-fast);
  -webkit-tap-highlight-color: transparent;
  
  &:hover {
    background: rgba(102, 126, 234, 0.1);
  }
`;

const SectionIcon = styled.span`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  margin-right: var(--space-sm);
  
  font-size: var(--fs-base);
  background: ${props => props.$color
    ? `${props.$color}20`
    : 'rgba(56, 189, 248, 0.1)'};
  border-radius: var(--radius-md);
`;

const SectionTitle = styled.span`
  flex: 1;
  text-align: left;
`;

const Chevron = styled(motion.span)`
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--fs-sm);
`;

const SectionItems = styled(motion.div)`
  overflow: hidden;
  margin-top: var(--space-xs);
  margin-left: var(--space-lg);
  
  @media (min-width: 1024px) {
    margin-left: var(--space-md);
  }
`;

const MenuItem = styled.button`
  display: flex;
  align-items: center;
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  
  background: ${props => props.$active
    ? 'rgba(102, 126, 234, 0.2)'
    : 'transparent'};
  border: none;
  border-left: ${props => props.$active
    ? '3px solid #667eea'
    : '3px solid transparent'};
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  
  color: ${props => props.$active ? '#667eea' : '#cbd5e1'};
  font-size: var(--fs-base);
  font-weight: var(--fw-medium);
  
  cursor: pointer;
  transition: all var(--transition-fast);
  -webkit-tap-highlight-color: transparent;
  min-height: 48px;
  
  &:hover {
    background: ${props => props.$active
    ? 'rgba(102, 126, 234, 0.3)'
    : 'rgba(148, 163, 184, 0.05)'};
  }
  
  &:active {
    transform: scale(0.98);
  }
`;

const ItemIcon = styled.span`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  margin-right: var(--space-sm);
  font-size: var(--fs-base);
`;

const ItemLabel = styled.span`
  flex: 1;
  text-align: left;
`;

const LogoutButton = styled.button`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  gap: var(--space-sm);
  padding: var(--space-md);
  margin-top: var(--space-lg);
  
  background: rgba(239, 68, 68, 0.1);
  border: 1px solid rgba(239, 68, 68, 0.2);
  border-radius: var(--radius-lg);
  
  color: #ef4444;
  font-size: var(--fs-base);
  font-weight: var(--fw-semibold);
  
  cursor: pointer;
  transition: all var(--transition-fast);
  -webkit-tap-highlight-color: transparent;
  min-height: 48px;
  
  &:hover {
    background: rgba(239, 68, 68, 0.2);
  }
  
  &:active {
    transform: scale(0.98);
  }
  
  @media (min-width: 1024px) {
    margin-top: var(--space-md);
  }
`;

// Desktop Sidebar
const DesktopNav = styled.nav`
  width: 260px;
  background: #1e293b;
  padding: var(--space-lg);
  box-shadow: 2px 0 10px rgba(0, 0, 0, 0.3);
  border-right: 1px solid #334155;
  height: 100vh;
  position: sticky;
  top: 0;
  display: none;
  
  @media (min-width: 1024px) {
    display: flex;
    flex-direction: column;
  }
`;

const DesktopLogo = styled.div`
  font-size: var(--fs-2xl);
  font-weight: var(--fw-bold);
  color: #38bdf8;
  margin-bottom: var(--space-xl);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) 0;
`;

const DesktopSection = styled.div`
  margin-bottom: var(--space-md);
`;

const DesktopSectionHeader = styled.div`
  display: flex;
  align-items: center;
  padding: var(--space-sm) var(--space-md);
  cursor: pointer;
  border-radius: var(--radius-md);
  color: ${props => props.$expanded ? '#667eea' : '#94a3b8'};
  background: ${props => props.$expanded
    ? 'rgba(102, 126, 234, 0.1)'
    : 'transparent'};
  transition: all 0.3s ease;
  margin-bottom: var(--space-xs);
  
  &:hover {
    background: rgba(102, 126, 234, 0.1);
  }
`;

const DesktopSectionIcon = styled.span`
  margin-right: var(--space-sm);
  font-size: var(--fs-base);
`;

const DesktopSectionTitle = styled.span`
  font-weight: var(--fw-semibold);
  font-size: var(--fs-sm);
  flex: 1;
`;

const DesktopChevron = styled(motion.div)`
  font-size: var(--fs-xs);
  color: inherit;
`;

const DesktopSectionContent = styled(motion.div)`
  overflow: hidden;
  margin-left: var(--space-md);
`;

const DesktopMenuItem = styled.div`
  display: flex;
  align-items: center;
  padding: var(--space-sm) var(--space-md);
  margin: 2px 0;
  cursor: pointer;
  border-radius: var(--radius-md);
  
  background: ${props => props.$active
    ? 'rgba(102, 126, 234, 0.2)'
    : 'transparent'};
  color: ${props => props.$active ? '#667eea' : '#cbd5e1'};
  border-left: ${props => props.$active
    ? '3px solid #667eea'
    : '3px solid transparent'};
  
  transition: all 0.3s ease;
  
  &:hover {
    background: ${props => props.$active
    ? 'rgba(102, 126, 234, 0.3)'
    : 'rgba(148, 163, 184, 0.05)'};
  }
`;

const DesktopItemIcon = styled.span`
  margin-right: var(--space-sm);
  font-size: var(--fs-sm);
`;

const DesktopItemLabel = styled.span`
  font-size: var(--fs-sm);
`;

const DesktopLogout = styled.div`
  margin-top: auto;
  padding-top: var(--space-md);
  border-top: 1px solid rgba(148, 163, 184, 0.1);
`;

const DesktopLogoutButton = styled.div`
  display: flex;
  align-items: center;
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-md);
  cursor: pointer;
  color: #94a3b8;
  background: transparent;
  border: none;
  min-height: 44px;
  
  transition: all 0.3s ease;
  
  &:hover {
    background: #334155;
    color: #f8fafc;
  }
  
  span {
    margin-right: var(--space-xs);
  }
`;

// Layout responsivo
const ResponsiveLayoutWrapper = styled.div`
  display: flex;
  min-height: 100vh;
  background: #0f172a;
`;

const MainContent = styled.main`
  flex: 1;
  overflow-y: auto;
  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  min-height: 100vh;
  
  /* Desktop: adiciona margem para sidebar */
  @media (min-width: 1024px) {
    margin-left: 0;
  }
`;

// ============= MENU SECTIONS CONFIG =============

const menuSections = [
  {
    id: 'finance',
    title: '💰 Finanças',
    icon: '💰',
    color: '#10b981',
    items: [
      { id: 'home', label: 'Início', icon: '🏠' },
      { id: 'dashboard', label: 'Dashboard', icon: '📊' },
      { id: 'transactions', label: 'Transações', icon: '💳' },
      { id: 'categories', label: 'Categorias', icon: '🏷️' },
      { id: 'reports', label: 'Relatórios', icon: '📄' }
    ]
  },
  {
    id: 'planning',
    title: '📅 Planejamento',
    icon: '📅',
    color: '#f59e0b',
    items: [
      { id: 'fixed', label: 'Gastos Fixos', icon: '🏠' },
      { id: 'shopping', label: 'Lista de Compras', icon: '🛒' }
    ]
  },
  {
    id: 'account',
    title: '👤 Conta',
    icon: '👤',
    color: '#8b5cf6',
    items: [
      { id: 'profile', label: 'Perfil', icon: '⚙️' }
    ]
  }
];

// ============= DESKTOP SIDEBAR COMPONENT =============

export function DesktopSidebar({ activePage, onNavigate, onLogout }) {
  const [expandedSections, setExpandedSections] = useState(['finance', 'planning', 'account']);

  const toggleSection = (sectionId) => {
    setExpandedSections(prev =>
      prev.includes(sectionId)
        ? prev.filter(id => id !== sectionId)
        : [...prev, sectionId]
    );
  };

  return (
    <DesktopNav>
      <DesktopLogo>🚀 CashPilot</DesktopLogo>

      {menuSections.map((section) => (
        <DesktopSection key={section.id}>
          <DesktopSectionHeader
            $expanded={expandedSections.includes(section.id)}
            onClick={() => toggleSection(section.id)}
          >
            <DesktopSectionIcon>{section.icon}</DesktopSectionIcon>
            <DesktopSectionTitle>{section.title}</DesktopSectionTitle>
            <DesktopChevron
              animate={{ rotate: expandedSections.includes(section.id) ? 0 : -90 }}
              transition={{ duration: 0.2 }}
            >
              <FaChevronDown />
            </DesktopChevron>
          </DesktopSectionHeader>

          <AnimatePresence>
            {expandedSections.includes(section.id) && (
              <DesktopSectionContent
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                transition={{ duration: 0.2 }}
              >
                {section.items.map((item) => (
                  <DesktopMenuItem
                    key={item.id}
                    $active={activePage === item.id}
                    onClick={() => onNavigate(item.id)}
                  >
                    <DesktopItemIcon>{item.icon}</DesktopItemIcon>
                    <DesktopItemLabel>{item.label}</DesktopItemLabel>
                  </DesktopMenuItem>
                ))}
              </DesktopSectionContent>
            )}
          </AnimatePresence>
        </DesktopSection>
      ))}

      <DesktopLogout>
        <DesktopLogoutButton onClick={onLogout}>
          <span>🚪</span>
          <span>Sair</span>
        </DesktopLogoutButton>
      </DesktopLogout>
    </DesktopNav>
  );
}

// ============= MOBILE MENU COMPONENT =============

export default function MobileMenu({ activePage, onNavigate, onLogout }) {
  const [isOpen, setIsOpen] = useState(false);
  const [expandedSections, setExpandedSections] = useState(['finance', 'planning', 'account']);

  // Close menu when navigating on mobile
  const handleNavigate = useCallback((pageId) => {
    onNavigate(pageId);
    setIsOpen(false);
  }, [onNavigate]);

  const toggleSection = (sectionId) => {
    setExpandedSections(prev =>
      prev.includes(sectionId)
        ? prev.filter(id => id !== sectionId)
        : [...prev, sectionId]
    );
  };

  // Lock body scroll when menu is open on mobile
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }

    return () => {
      document.body.style.overflow = '';
    };
  }, [isOpen]);

  return (
    <MobileMenuContainer>
      {/* Mobile Header */}
      <MobileHeader>
        <MobileLogo>🚀 CashPilot</MobileLogo>
        <MenuToggle onClick={() => setIsOpen(true)} aria-label="Abrir menu">
          <FaBars />
        </MenuToggle>
      </MobileHeader>

      {/* Mobile Menu Overlay */}
      <AnimatePresence>
        {isOpen && (
          <>
            <Overlay
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsOpen(false)}
            />
            <MenuPanel
              initial={{ x: '100%' }}
              animate={{ x: 0 }}
              exit={{ x: '100%' }}
              transition={{ type: 'spring', damping: 25, stiffness: 300 }}
            >
              <MenuHeader>
                <MenuLogo>🚀 CashPilot</MenuLogo>
                <CloseButton onClick={() => setIsOpen(false)} aria-label="Fechar menu">
                  <FaTimes />
                </CloseButton>
              </MenuHeader>

              <MenuContent>
                {menuSections.map((section) => (
                  <Section key={section.id}>
                    <SectionHeader
                      $expanded={expandedSections.includes(section.id)}
                      onClick={() => toggleSection(section.id)}
                    >
                      <SectionIcon $color={section.color}>
                        {section.icon}
                      </SectionIcon>
                      <SectionTitle>{section.title}</SectionTitle>
                      <Chevron
                        animate={{
                          rotate: expandedSections.includes(section.id) ? 180 : 0
                        }}
                        transition={{ duration: 0.2 }}
                      >
                        <FaChevronDown />
                      </Chevron>
                    </SectionHeader>

                    <AnimatePresence>
                      {expandedSections.includes(section.id) && (
                        <SectionItems
                          initial={{ opacity: 0, height: 0 }}
                          animate={{ opacity: 1, height: 'auto' }}
                          exit={{ opacity: 0, height: 0 }}
                          transition={{ duration: 0.2 }}
                        >
                          {section.items.map((item) => (
                            <MenuItem
                              key={item.id}
                              $active={activePage === item.id}
                              onClick={() => handleNavigate(item.id)}
                            >
                              <ItemIcon>{item.icon}</ItemIcon>
                              <ItemLabel>{item.label}</ItemLabel>
                            </MenuItem>
                          ))}
                        </SectionItems>
                      )}
                    </AnimatePresence>
                  </Section>
                ))}

                <LogoutButton onClick={onLogout}>
                  <FaSignOutAlt />
                  <span>Sair</span>
                </LogoutButton>
              </MenuContent>
            </MenuPanel>
          </>
        )}
      </AnimatePresence>
    </MobileMenuContainer>
  );
}

// ============= RESPONSIVE LAYOUT COMPONENT =============

export function ResponsiveLayout({
  children,
  activePage,
  onNavigate,
  onLogout
}) {
  return (
    <ResponsiveLayoutWrapper>
      {/* Desktop Sidebar - Hidden on mobile */}
      <DesktopSidebar
        activePage={activePage}
        onNavigate={onNavigate}
        onLogout={onLogout}
      />

      {/* Mobile Menu - Hidden on desktop */}
      <MobileMenu
        activePage={activePage}
        onNavigate={onNavigate}
        onLogout={onLogout}
      />

      {/* Main Content */}
      <MainContent>
        {children}
      </MainContent>
    </ResponsiveLayoutWrapper>
  );
}
